package net.plainnotes.app.attachmentpoc;

import android.content.ContentProvider;
import android.content.ContentValues;
import android.database.Cursor;
import android.database.MatrixCursor;
import android.net.Uri;
import android.os.Build;
import android.os.ParcelFileDescriptor;
import android.provider.OpenableColumns;
import java.io.FileNotFoundException;
import java.io.IOException;

/** Test-APK provider: only generated bytes, no external URI, filesystem or user data access. */
public final class SyntheticStreamProvider extends ContentProvider {
    @Override public boolean onCreate() {
        SyntheticEmulatorGuard.requireEmulator();
        return true;
    }
    private String kind(Uri uri) {
        String path = uri.getLastPathSegment();
        if (!"unknown".equals(path) && !"failure".equals(path) && !"mime".equals(path))
            throw new IllegalArgumentException("Unsupported synthetic source");
        return path;
    }
    @Override public Cursor query(Uri uri, String[] projection, String selection, String[] args, String sort) {
        kind(uri);
        MatrixCursor cursor = new MatrixCursor(new String[]{OpenableColumns.DISPLAY_NAME, OpenableColumns.SIZE});
        cursor.addRow(new Object[]{"synthetic.bin", null});
        return cursor;
    }
    @Override public String getType(Uri uri) { return "mime".equals(kind(uri)) ? "image/png" : "application/octet-stream"; }
    @Override public ParcelFileDescriptor openFile(Uri uri, String mode) throws FileNotFoundException {
        if (!"r".equals(mode)) throw new FileNotFoundException("Synthetic read-only source");
        boolean failure = "failure".equals(kind(uri));
        final ParcelFileDescriptor[] pipe;
        try { pipe = ParcelFileDescriptor.createReliablePipe(); }
        catch (IOException e) { throw new FileNotFoundException("Synthetic pipe unavailable"); }
        Thread thread = new Thread(() -> {
            try {
                byte[] bytes = new byte[failure ? 1200 : 8192];
                for (int i = 0; i < bytes.length; i++) bytes[i] = (byte)((i * 31 + 17) % 251);
                // Keep the reliable descriptor open until closeWithError, so the read side sees the fault.
                try (ParcelFileDescriptor.AutoCloseOutputStream out = new ParcelFileDescriptor.AutoCloseOutputStream(pipe[1])) {
                    out.write(bytes); out.flush();
                    if (failure) pipe[1].closeWithError("Synthetic provider read failure");
                }
            } catch (IOException e) {
                try { pipe[1].closeWithError("Synthetic pipe closed"); } catch (IOException ignored) { /* test pipe already revoked */ }
            }
        }, "synthetic-source-pipe");
        thread.setDaemon(true); thread.start();
        return pipe[0];
    }
    @Override public Uri insert(Uri uri, ContentValues values) { throw new UnsupportedOperationException("Synthetic read-only"); }
    @Override public int update(Uri uri, ContentValues values, String selection, String[] args) { throw new UnsupportedOperationException("Synthetic read-only"); }
    @Override public int delete(Uri uri, String selection, String[] args) { throw new UnsupportedOperationException("Synthetic read-only"); }
}
